"""hook: 把拼音识别(快路径)挂到 Agent._predict_intent / A 路上(不改既有文件逻辑)

分领域开关（读【当前 profile 的 behavior】）:
    "fastpath_mode": "off" | "shadow" | "live"      # 默认 off
    "fastpath_table": "opencode_fastpath/table_x.json"   # 相对 voice_agent 根
    "fastpath_min_prefix": 3                          # 可选(两字命令用 2)
环境变量 OPENCODE_FASTPATH / OPENCODE_FASTPATH_TABLE / OPENCODE_MIN_PREFIX 作为普通测试的**覆盖**(优先生效)。

语义(严格加法):
  1) 先按 voice_agent 原逻辑跑(规则直通/embed/model) — 行为不变
  2) 仅当原逻辑给出 unknown 且拼音键命中时:
       shadow → 只记 rescue 日志, 仍返回原结果
       live   → 返回拼音识别结果(仅 additive 条目, 破坏性意图默认拦截)
  3) 其余情况只记对照日志, 从不改写结果
"""
from __future__ import annotations

import os
from pathlib import Path

from .fastpath import FastPath

ROOT = Path(__file__).resolve().parent.parent      # voice_agent 目录
HERE_SYS = Path(__file__).resolve().parent / "table_system.json"
_CACHE = {}
_INSTANCE = None


def _cfg_get(cfg, key, default=None):
    try:
        b = getattr(cfg, "behavior", None)
        if isinstance(b, dict) and key in b:
            return b.get(key)
    except Exception:
        pass
    return default


def resolve(cfg=None):
    """优先级: 当前 profile 的 behavior(分领域开关) > 环境变量(仅测试/兜底) > off

    ⚠️ 现在"哪些意图参与匹配"由【唯一开关】intent_config.json 的 intent_registry
       决定（见 opencode_fastpath/intents.py）；这个 resolve 只管**旧表机制**
       （table_*.json），只有当 behavior.fastpath_table 或 env 显式给了才启用，
       否则返回 None（= 用 registry）。
    """
    env_mode = os.environ.get("OPENCODE_FASTPATH")
    env_table = os.environ.get("OPENCODE_FASTPATH_TABLE")
    cfg_table = _cfg_get(cfg, "fastpath_table")
    if not env_mode and not env_table and not cfg_table and not _cfg_get(cfg, "fastpath_legacy"):
        return "off", None, None
    mode = _cfg_get(cfg, "fastpath_mode") or env_mode or "off"
    table = cfg_table or env_table
    minp = _cfg_get(cfg, "fastpath_min_prefix") or os.environ.get("OPENCODE_MIN_PREFIX")
    if table and not os.path.isabs(str(table)):
        table = str(ROOT / str(table))
    return str(mode), table, (int(minp) if minp else None)


def get_fp(cfg=None):
    global _INSTANCE
    mode, table, minp = resolve(cfg)
    if mode == "off":
        return None
    key = (mode, table, minp)
    fp = _CACHE.get(key)
    if fp is None:
        fp = FastPath(table_path=table, mode=mode)
        if minp:
            fp.min_prefix = int(minp)
        _CACHE[key] = fp
        try:
            from dlog import log as _log
            _log(f"[OPENCODE] 拼音识别 mode={fp.mode} entries={len(fp.entries)} "
                 f"table={fp.table_path} min_prefix={fp.min_prefix}", "SYS")
        except Exception:
            print(f"[OPENCODE] 拼音识别 mode={fp.mode} entries={len(fp.entries)} "
                  f"table={fp.table_path} min_prefix={fp.min_prefix}", flush=True)
    _INSTANCE = fp
    return fp


def get_system_fp(cfg=None):
    """[OPENCODE] 意图匹配表 = 唯一开关（intent_config.json 的 intent_registry）

    取代原来的 table_system.json / table_*.json → 域由"意图表"的标签+enabled 决定；
    每次调用都会按 mtime+size 检查是否热加载（改完 json 立即生效）。
    """
    try:
        from . import intents as _intents
        return _intents.get_fp(cfg)
    except Exception:
        return None


def install_for(cls):
    """给任意类打补丁(自检用假类; 生产传 voice_agent.Agent)"""
    orig = cls._predict_intent

    def patched(self, *a, **kw):
        fp = get_fp(getattr(self, "cfg", None))
        if fp is None:
            return orig(self, *a, **kw)
        txt = None
        for x in a:
            if isinstance(x, str):
                txt = x
                break
        if txt is None:
            txt = kw.get("text_override")
        fr = fp.route(txt) if txt else None
        if fr and fr["decision"] == "hit" and fp.mode == "live" and fr.get("additive") and not fr.get("blocked"):
            fp.observe(txt, {"intent": fr["intent"], "conf": 1.0, "src": "opencode_fastpath"}, fr)
            return {"text": txt, "intent": fr["intent"], "conf": 1.0,
                    "latency_ms": 0.0, "margin": 1.0, "src": "opencode_fastpath"}
        r = orig(self, *a, **kw)
        try:
            if txt:
                fp.observe(txt, r if isinstance(r, dict) else {}, fr)
        except Exception:
            pass
        return r

    patched.__name__ = "_predict_intent"
    patched.__doc__ = getattr(orig, "__doc__", "")
    cls._predict_intent = patched
    return cls


def install():
    import voice_agent
    install_for(voice_agent.Agent)
